const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let n = 0;
let s = '';
let lineCount = 0;

rl.on('line', (line) => {
    if (lineCount === 0) {
        n = parseInt(line.trim(), 10);
    } else if (lineCount === 1) {
        s = line.trim();
        rl.close();
    }
    lineCount++;
});

rl.on('close', () => {
    let countU = 0, countD = 0, countL = 0, countR = 0;
    for (let i = 0; i < n; i++) {
        const c = s[i];
        if (c === 'U') countU++;
        else if (c === 'D') countD++;
        else if (c === 'L') countL++;
        else if (c === 'R') countR++;
    }

    const vertical = 2 * Math.min(countU, countD);
    const horizontal = 2 * Math.min(countL, countR);

    console.log(vertical + horizontal);
});
